 'use strict';
let bulkMode=false,bulkPending=[];
const bulkSelected=new Set();
function bulkPrune(groups){const keys=new Set(groups.map(g=>g.key));for(const k of bulkSelected)if(!keys.has(k))bulkSelected.delete(k);}
function bulkControls(groups){bulkPrune(groups);return `<div class="bulk-bar" role="region" aria-label="批量管理工具"><label class="bulk-select-all"><input id="bulk-all" type="checkbox"><span>全选 ${groups.length} 个词汇</span></label><span id="bulk-count" role="status">已选 ${bulkSelected.size}</span>${notebookFilter?'<button class="btn primary" data-bulk="add">加入生词本</button>':''}<button class="btn" data-bulk="remove">移出生词本</button><button class="btn" data-action="export-options">${icon('download')}导出</button><p class="bulk-hint">移出生词本会保留原词汇册、全部来源和学习记录。</p></div>`;}
function bulkSync(){if(route!=='library'||!bulkMode)return;const groups=filteredGroups();bulkPrune(groups);const all=$('#bulk-all');if(all){all.checked=groups.length>0&&bulkSelected.size===groups.length;all.indeterminate=bulkSelected.size>0&&bulkSelected.size<groups.length;all.disabled=!groups.length;}if($('#bulk-count'))$('#bulk-count').textContent=`已选 ${bulkSelected.size}`;document.querySelectorAll('[data-bulk="add"],[data-bulk="remove"]').forEach(b=>b.disabled=!bulkSelected.size);document.querySelectorAll('[data-bulk-entry]').forEach(el=>{el.checked=bulkSelected.has(el.dataset.bulkEntry);el.closest('.word-card').classList.toggle('bulk-selected',el.checked);});}
function bulkAfterRender(){if(route!=='library'){bulkMode=false;bulkSelected.clear();}document.body.classList.toggle('bulk-managing',bulkMode&&route==='library');bulkSync();}
function deleteRecordIds(ids){const entries=state.entries.filter(e=>ids.includes(e.id));if(!entries.length)return 0;state=V.removeRecords(state,ids);if(!persist())return null;entries.forEach(e=>cancelEntryTranslation(e.id));return entries.length;}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-bulk]');if(!el)return;if(el.dataset.bulk==='toggle'){bulkMode=!bulkMode;bulkSelected.clear();render();return;}if(['add','remove'].includes(el.dataset.bulk)){bulkPrune(filteredGroups());changeMark([...bulkSelected],el.dataset.bulk==='add');}});
document.addEventListener('change',ev=>{if(!bulkMode||route!=='library')return;if(ev.target.id==='bulk-all'){for(const g of filteredGroups())ev.target.checked?bulkSelected.add(g.key):bulkSelected.delete(g.key);bulkSync();}if(ev.target.dataset.bulkEntry){const k=ev.target.dataset.bulkEntry;ev.target.checked?bulkSelected.add(k):bulkSelected.delete(k);bulkSync();}});
